sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // 1. Validate start_time exists
    if (current.start_time.nil()) {
        gs.addErrorMessage('Start time is required for an appointment.');
        current.setAbortAction(true);
        return;
    }

    var startGdt = new GlideDateTime(current.start_time);

    // 2. Compute end_time if not provided
    if (current.end_time.nil()) {
        var duration = parseInt(current.duration_minutes, 10);
        if (isNaN(duration) || duration <= 0) {
            duration = 30; // Default 30 minutes
            current.duration_minutes = 30;
        }
        var endGdt = new GlideDateTime(startGdt);
        endGdt.addSeconds(duration * 60);
        current.end_time = endGdt.getValue();
    } else {
        // Ensure duration_minutes matches the interval if provided
        var endGdtExplicit = new GlideDateTime(current.end_time);
        var diffMs = endGdtExplicit.getNumericValue() - startGdt.getNumericValue();
        if (diffMs > 0) {
            current.duration_minutes = Math.round(diffMs / 60000);
        }
    }

    // 3. Validate end_time > start_time
    var finalEndGdt = new GlideDateTime(current.end_time);
    if (finalEndGdt.getNumericValue() <= startGdt.getNumericValue()) {
        gs.warn('[ApolloAppointment] Invalid time range for appointment ' + 
            (current.number || 'NEW') + ': end_time (' + current.end_time + 
            ') <= start_time (' + current.start_time + ') | User: ' + gs.getUserName());
        gs.addErrorMessage('Appointment end time must be after start time.');
        current.setAbortAction(true);
    }

})(current, previous);
